(()=>{var S=document.querySelectorAll(".cassette-tape");S.forEach(e=>{let t=e.querySelector("audio"),m=e.querySelector(".play"),y=e.querySelector(".pause"),a=e.querySelector(".progress"),h=e.querySelector(".elapsed"),i=e.querySelector(".handle"),f=e.querySelector(".remaining"),p=e.querySelector(".current-time"),E=e.querySelector(".duration"),c=window.innerWidth<640?28:38,o=!0;i.style.color="white",setInterval(function(){t.paused?(i.style.color="white",o=!0):(o=!o,i.style.color=o?"white":"#030303")},500);function d(n){return Math.floor(n/60)+":"+String(Math.floor(n%60)).padStart(2,"0")}function l(){let n=isFinite(t.duration)?t.duration:0,r=t.currentTime||0,u=n>0?r/n:0,s=Math.min(Math.round(u*(c-1)),c-1);h.textContent="+".repeat(s),f.textContent="-".repeat(c-1-s),p.textContent=d(r),E.textContent=n?d(n):"0:00"}t.addEventListener("timeupdate",l),t.addEventListener("loadedmetadata",l),a.addEventListener("click",function(n){if(!t.duration)return;let r=a.getBoundingClientRect(),u=Math.max(0,Math.min(1,(n.clientX-r.left)/r.width));t.currentTime=u*t.duration}),m.addEventListener("click",function(){t.play()}),y.addEventListener("click",function(){t.pause()}),l()});})();
